import{_ as n}from"./chunks/image12.BRgDBKom.js";import{_ as i,o as a,c as r,am as t,j as o}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/video1.BuIh58OI.mp4",l="/projects/AiMechaM1/en/advanced-kit/assets/image2.POFdt0-r.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.SQOIX7cJ.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image4.ChVrbHte.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image5.44wpyHYa.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image6.CKA_q74e.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image7.Dl1xESxI.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image8.AGgiegZb.png",q=JSON.parse('{"title":"3.32 Lesson 32: Embodied Intelligence Collaborative Application","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.32 Lesson 32 Embodied Intelligence Collaborative Application.md","filePath":"docs/3. Course materials/3.32 Lesson 32 Embodied Intelligence Collaborative Application.md"}'),u={name:"docs/3. Course materials/3.32 Lesson 32 Embodied Intelligence Collaborative Application.md"};function f(b,e,v,w,y,k){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-32-lesson-32-embodied-intelligence-collaborative-application" tabindex="-1">3.32 Lesson 32: Embodied Intelligence Collaborative Application <a class="header-anchor" href="#_3-32-lesson-32-embodied-intelligence-collaborative-application" aria-label="Permalink to &quot;3.32 Lesson 32: Embodied Intelligence Collaborative Application&quot;">​</a></h1><h2 id="_3-32-1-lesson-introduction" tabindex="-1">3.32.1 Lesson Introduction <a class="header-anchor" href="#_3-32-1-lesson-introduction" aria-label="Permalink to &quot;3.32.1 Lesson Introduction&quot;">​</a></h2><p>This lesson focuses on multi-action collaborative composite commands, achieving the transition from single-step responses to multi-step task execution. Starting from everyday scenarios such as issuing a single command for &quot;opening windows, adjusting air conditioning, and playing music&quot;, the curriculum covers the long-command parsing workflow: speech-to-text transcription, intent analysis, action decomposition and sequencing, and sequential execution with feedback. Practical exercises coordinate ultrasonic ranging with robotic arm grasping to program a complete task chain, from moving forward → measuring distance → confirming the target → grasping → lifting the arm, integrating movement, perception, robotic arm manipulation, and gripper control. Design custom composite commands to explore multi-tool collaboration paradigms. This progression marks the evolution from isolated skills to system integration, upgrading the robot into an autonomous task executor and serving as both a comprehensive capstone and a launchpad for advanced exploration.</p><h2 id="_3-32-2-learning-objectives" tabindex="-1">3.32.2 Learning Objectives <a class="header-anchor" href="#_3-32-2-learning-objectives" aria-label="Permalink to &quot;3.32.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the definition and characteristics of long or composite commands, master the five-step processing workflow for long-command parsing in large models, comprehend the system architecture of multi-tool temporal coordination, and learn the principles of action decomposition and atomic action sequencing.</p></li><li><p>Program and implement collaborative invocation across multiple MCP tools, design a complete task chain under composite commands integrating chassis movement + environmental perception + robotic arm grasping, and manage the temporal coordination between ultrasonic ranging and robotic arm actuation.</p></li><li><p>Establish a systems mindset for task decomposition and temporal orchestration, cultivate engineering integration skills for multi-module collaboration, reinforce the cognitive leap from single-step response to multi-step execution, and strengthen problem decomposition and planning capabilities for complex tasks.</p></li><li><p>Relate the concepts to real-world application scenarios such as smart speaker multi-device control, in-vehicle voice assistant multi-action execution, and service robot composite tasks to understand how long-command parsing elevates the human-robot interaction experience.</p></li></ol><h2 id="_3-32-3-preparation" tabindex="-1">3.32.3 Preparation <a class="header-anchor" href="#_3-32-3-preparation" aria-label="Permalink to &quot;3.32.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Long-Command Core Concepts</strong>:</p><ul><li><p><strong>Definition</strong>: A long command is a natural language instruction containing multiple actions or intents, such as &quot;Open the car window and turn off the air conditioner&quot;. Whereas traditional voice assistants only recognize single-intent commands, large models comprehend composite semantics and decompose them into sequential steps for execution.</p></li><li><p><strong>Five-Step Processing Workflow</strong>:</p><ol><li><p>Speech Recognition: Transcribes spoken audio into text.</p></li><li><p>Intent Parsing: Analyzes the multiple action intents and logical relationships contained within the transcribed text.</p></li><li><p>Action Decomposition and Sequencing: Breaks the long command down into individual atomic actions and orders them into a sequential execution pipeline.</p></li><li><p>Execution and Feedback: Invokes the corresponding hardware control interfaces step by step, providing voice progress feedback after each completed action.</p></li><li><p>Exception Handling: Halts subsequent actions and reports the cause of failure if any atomic action fails during execution.</p></li></ol></li></ul><p><strong>Atomic Actions and Collaboration</strong>:</p><ul><li><p><strong>Atomic Action</strong>: A fundamental operation that cannot be subdivided further, such as &quot;Move forward 10 centimeters&quot;, &quot;Open the gripper&quot;, or &quot;Measure distance once&quot;.</p></li><li><p><strong>Action Orchestration</strong>: Combining multiple atomic actions into a complex task according to temporal order and conditional logic.</p></li><li><p><strong>Multi-Tool Collaboration</strong>: Invoking multiple MCP tools, including motors + the ultrasonic sensor + the robotic arm + the gripper, within a single task to achieve an objective through sequential coordination.</p></li></ul><p><strong>Application Cases</strong>:</p><ul><li><p>Xiaomi Auto Voice Assistant: Executes three distinct actions, opening the window + adjusting the air conditioner + playing music, from a single spoken sentence.</p></li><li><p>Smart Speaker Whole-Home Control: Speaking the phrase &quot;Back home now&quot; automatically turns on the lights + activates the air conditioner + closes the curtains + plays music.</p></li><li><p>Industrial Robot Task Orchestration: Executing &quot;Grasp the workpiece and place it on the conveyor belt&quot; coordinates multiple steps, including localization, grasping, transfer, and placement.</p></li><li><p>Service Robot Delivery: Executing &quot;Deliver a cola to Table 3&quot; completes an end-to-end workflow encompassing navigation, item pickup, table delivery, and return.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the glowing ultrasonic sensor to <strong>port K</strong>.</p></li><li><p>Connect the three bus servos in series to bus ports S1 or S2, where ID 1 = gripper, ID 2 = forearm, and ID 3 = upper arm.</p></li></ul><p><strong>Involved MCP Tool List</strong>:</p><ul><li><p>Motor Speed: Controls the rotational speeds of all four wheels for chassis movement.</p></li><li><p>Move Distance: Precisely controls movement direction, rotational speed, and travel distance.</p></li><li><p>Glowing Ultrasonic: Measures the distance to obstacles ahead.</p></li><li><p>Robotic Arm Motion: Controls the Y and Z end-effector coordinates and movement duration of the robotic arm.</p></li><li><p>Gripper: Controls the opening and closing angle of the mechanical gripper via bus servo ID 1.</p></li></ul><h2 id="_3-32-4-practical-implementation" tabindex="-1">3.32.4 Practical Implementation <a class="header-anchor" href="#_3-32-4-practical-implementation" aria-label="Permalink to &quot;3.32.4 Practical Implementation&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a multi-tool collaborative embodied intelligence system driven by large model long commands, centered on composite command parsing and temporal orchestration. The K230 microphone captures natural language instructions while the ultrasonic sensor measures obstacle distances in real time. The cloud large model parses the multi-step logical relationships within the composite command and decomposes them into an atomic action sequence. Acting as a scheduler, the decision-making layer sequentially invokes the motor, ultrasonic, robotic arm, and gripper MCP tools, advancing to the next step only after receiving &quot;ok&quot; feedback from the current action. The execution layer coordinates four-wheel Mecanum omnidirectional movement, ultrasonic distance evaluation, and three-servo robotic arm grasping and lifting. A complete task chain, moving forward → stopping when the obstacle distance reaches 14 cm or less → confirming position → opening the gripper → extending the arm to grasp → clamping the gripper → lifting the arm, seamlessly integrates mobility, perception, and manipulation. Under long-command mode, the robot plans and executes tasks autonomously, progressing from simple command &quot;obedience&quot; to &quot;autonomous task comprehension and completion&quot;.</p>',23),o("p",null,[o("video",{controls:"",playsinline:"",preload:"metadata",src:s})],-1),t('<p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Result retrieval</td><td style="text-align:center;"><img loading="lazy" height="72" width="466" src="'+l+'" class="common_img" style="width:100px;aspect-ratio:466 / 72;"></td><td style="text-align:left;">Reads the large model output and stores it in a variable to ensure data consistency.</td></tr><tr><td style="text-align:center;">Movement control</td><td style="text-align:center;"><img loading="lazy" height="40" width="477" src="'+c+'" class="common_img" style="width:100px;aspect-ratio:477 / 40;"></td><td style="text-align:left;">Evaluates whether the motor speed tool is invoked to control the rotational speeds of all four wheels.</td></tr><tr><td style="text-align:center;">Precision movement</td><td style="text-align:center;"><img loading="lazy" height="40" width="490" src="'+d+'" class="common_img" style="width:100px;aspect-ratio:490 / 40;"></td><td style="text-align:left;">Evaluates whether the movement distance tool is invoked to precisely control direction, speed, and travel distance.</td></tr><tr><td style="text-align:center;">Ranging tool</td><td style="text-align:center;"><img loading="lazy" height="42" width="580" src="'+p+'" class="common_img" style="width:100px;aspect-ratio:580 / 42;"></td><td style="text-align:left;">Evaluates whether the ultrasonic ranging tool is invoked to obtain the distance to obstacles ahead.</td></tr><tr><td style="text-align:center;">Gripper control</td><td style="text-align:center;"><img loading="lazy" height="49" width="468" src="'+m+'" class="common_img" style="width:100px;aspect-ratio:468 / 49;"></td><td style="text-align:left;">Controls the angle of bus servo ID 1 to open and clamp the mechanical gripper.</td></tr><tr><td style="text-align:center;">Result feedback</td><td style="text-align:center;"><img loading="lazy" height="48" width="386" src="'+h+'" class="common_img" style="width:100px;aspect-ratio:386 / 48;"></td><td style="text-align:left;">Sends tool execution results back to the large model to trigger the next scheduled action.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task: Forward Movement, Ranging, and Grasping Collaborative Task Under Composite Commands</strong></p><ul><li><p>Initialization settings: Upon startup, wait 6 seconds and play note B5 for a 1/8 beat as the startup prompt tone. Initialize port A, configure the Wi-Fi SSID as <code>Hiwonder</code> and the password as <code>hiwonder2026</code>, load the default MCP configuration, set the operating mode to online large model, initialize the linkage robotic arm, and play note B6 for a 1/8 beat as the readiness prompt tone.</p></li><li><p>Main loop structure: Start detection execution and repeatedly update and save result data.</p></li><li><p>Result retrieval branch: If <code>Does result exist?</code> returns true, store the retrieved recognition result in the AIresult variable.</p></li><li><p>Motor speed branch: If AIresult contains the default MCP tool name for motor speed, set the front-left, rear-left, front-right, and rear-right wheel speeds of the Mecanum-wheel car to the respective motor speed parameters extracted from AIresult, and send a response result with dictionary key <code>result</code> and value <code>ok</code>.</p></li><li><p>Movement distance branch: If AIresult contains the default MCP tool name for movement distance, command the Mecanum-wheel car to translate at the rotational speed in rpm, toward the directional angle in degrees, and for the distance in centimeters extracted from AIresult, then send the response result <code>ok</code>.</p></li><li><p>Ultrasonic ranging branch: If AIresult contains the default MCP tool name for glowing ultrasonic distance measurement, send a response result with dictionary key <code>result</code> and a value concatenating the obstacle distance in centimeters measured by the ultrasonic sensor with the unit string <code>cm</code>, returning the distance data to the large model for decision-making.</p></li><li><p>Robotic arm motion branch: If AIresult contains the default MCP tool name for robotic arm motion, move the robotic arm end effector to the forward-backward Y-axis coordinate in millimeters and vertical Z-axis coordinate in millimeters extracted from AIresult over the specified duration in milliseconds, and send the response result <code>ok</code>.</p></li><li><p>Mechanical gripper branch: If AIresult contains the default MCP tool name for the mechanical gripper, set bus servo ID 1 to the target angle in degrees over the duration in milliseconds extracted from AIresult, and send the response result <code>ok</code>.</p></li></ul><img loading="lazy" height="619" width="1470" src="'+g+'" class="common_img" style="width:800px;aspect-ratio:1470 / 619;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Embodied AI Collaboration</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software and select the CH340 COM port from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload and run the compiled program on the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-32-5-expansion-and-advancement" tabindex="-1">3.32.5 Expansion and Advancement <a class="header-anchor" href="#_3-32-5-expansion-and-advancement" aria-label="Permalink to &quot;3.32.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Multi-Step Material Handling Robot</strong></p><p>Design a complete material handling composite task: &quot;Start from the starting point, move to the front of the block, pick up the block, turn left 90 degrees, move forward to the target zone, put the block down, and then return to the starting point.&quot; Express the entire task in a single natural language command to verify whether the large model can accurately decompose it into multiple action steps and execute them sequentially. Explore the depth of long-command task orchestration, understand how embodied intelligence upgrades from single-step operations to complete task execution, and simulate the workflow of an industrial material handling robot.</p><p><strong>Expansion Project 2: Vision and Ultrasonic Dual-Perception Collaborative Grasping</strong>. Integrate the two perception capabilities of large vision model recognition and ultrasonic ranging to design an intelligent grasping task: first use the vision foundation model to identify the category and position of an object ahead, then confirm the distance through precise ultrasonic ranging, and finally control the robotic arm to complete the grasp. Explore multi-perception fusion in embodied intelligence systems and understand how different sensors complement each other: vision identifies what the object is while ultrasonic ranging precisely measures the distance, working in tandem to improve grasping success rates and build a smarter robotic perception system.</p><h2 id="_3-32-6-q-a" tabindex="-1">3.32.6 Q&amp;A <a class="header-anchor" href="#_3-32-6-q-a" aria-label="Permalink to &quot;3.32.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is long-command parsing?</strong></p><p><strong>Answer</strong>: Long-command parsing enables AI to <strong>comprehend composite instructions containing multiple action intents</strong> and automatically decompose them into sequential steps for execution. Traditional voice assistants cannot accomplish this, whereas large models succeed due to the fundamental technological leap from rigid &quot;keyword matching&quot; to &quot;deep semantic comprehension&quot;.</p><p><strong>Q2: In the composite task of this lesson, the local program does not explicitly hard-code the sequential logic of moving forward first, measuring distance second, and grasping third. Why is the robot still able to execute these steps in the proper order?</strong></p><p><strong>Answer</strong>: This highlights the most critical takeaway of the lesson: <strong>the action sequence is orchestrated by the cloud-based large model rather than hard-coded in the local program</strong>. The local program functions as an &quot;actuator&quot;, while the large model acts as the &quot;commander&quot;.</p><h2 id="_3-32-7-technical-support-and-discussion" tabindex="-1">3.32.7 Technical Support and Discussion <a class="header-anchor" href="#_3-32-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.32.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',21)])])}const C=i(u,[["render",f]]);export{q as __pageData,C as default};
